function add(a, b) {
  return a + b;
}

const multiply = function (a, b) {
  return a * b;
};

console.log(multiply(2, 3)); // works AFTER the assignment

function invoice(currency = 'USD', ...amounts) {
  const total = amounts.reduce((a, b) => a + b, 0);
  return currency + ' ' + total;
}

console.log(invoice());            // 'USD 0'
console.log(invoice('EUR', 10, 5)); // 'EUR 15'
console.log(invoice(undefined, 7)); // 'USD 7'

